    assertTrue(metadataString.contains("<edmx:Reference " + "Uri=\"http://localhost/odata/odata/v4.0/referenceWithTwoIncludes\">" + "<edmx:Include Namespace=\"Org.OData.Core.2\" Alias=\"Core2\"/>" + "<edmx:Include Namespace=\"Org.OData.Core.3\" Alias=\"Core3\"/>" + "</edmx:Reference>"));
