    assertTrue(metadataString.contains("<edmx:Reference Uri=\"http://localhost/odata/odata/v4.0/referenceWithAllAndNull\">" + "<edmx:Include Namespace=\"referenceWithAllAndNull.1\"/>" + "<edmx:Include Namespace=\"referenceWithAllAndNull.2\"/>" + "<edmx:IncludeAnnotations TermNamespace=\"ReferenceWithAllTermNs.4\"/>" + "<edmx:IncludeAnnotations TermNamespace=\"ReferenceWithAllTermAndNullNs.5\" Qualifier=\"Q.5\"/>" + "<edmx:IncludeAnnotations TermNamespace=\"ReferenceWithAllTermAndNullNs.6\" " + "TargetNamespace=\"TargetNS\"/>" + "<edmx:IncludeAnnotations TermNamespace=\"ReferenceWithAllTermAndNullNs.7\"/>" + "</edmx:Reference>"));
